/*
 * Normaliza Gmail y compara sus IDs con la hoja de control.
 * No usa .item: trabaja con colecciones explícitas para evitar
 * "Multiple matching items" cuando llegan varios mensajes.
 */

const mensajes = $('Mensajes Recibidos').all().map((item) => item.json ?? {});
const filasProcesadas = $input.all().map((item) => item.json ?? {});

const registrosPorId = new Map();
for (const fila of filasProcesadas) {
  const id = String(fila.id ?? '').trim();
  if (id) registrosPorId.set(id, fila);
}

function limpiarPrefijo(valor, nombre) {
  return String(valor ?? '')
    .replace(new RegExp('^' + nombre + ':\\s*', 'i'), '')
    .trim();
}

function obtenerHeader(correo, nombre) {
  const buscado = nombre.toLowerCase();
  const headers = correo.headers;

  if (headers && !Array.isArray(headers) && typeof headers === 'object') {
    const clave = Object.keys(headers).find((key) => key.toLowerCase() === buscado);
    if (clave) {
      const valor = Array.isArray(headers[clave]) ? headers[clave][0] : headers[clave];
      return limpiarPrefijo(valor, nombre);
    }
  }

  const headersPayload = correo.payload?.headers;
  if (Array.isArray(headersPayload)) {
    const encontrado = headersPayload.find(
      (header) => String(header.name ?? '').toLowerCase() === buscado,
    );
    if (encontrado) return String(encontrado.value ?? '').trim();
  }

  return '';
}

function datosDireccion(correo, valor, nombreHeader) {
  if (valor && typeof valor === 'object') {
    const primero = Array.isArray(valor) ? valor[0] : valor.value?.[0];
    if (primero && typeof primero === 'object') {
      return {
        email: String(primero.address ?? '').trim().toLowerCase(),
        nombre: String(primero.name ?? '').trim(),
      };
    }
  }

  const texto = limpiarPrefijo(valor || obtenerHeader(correo, nombreHeader), nombreHeader);
  const emailEncontrado = texto.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  const email = String(emailEncontrado?.[0] ?? '').toLowerCase();
  const nombre = email
    ? texto.replace(emailEncontrado[0], '').replace(/[<>"']/g, '').replace(/^[,;\s]+|[,;\s]+$/g, '').trim()
    : '';
  return { email, nombre };
}

function decodificarBase64Url(valor) {
  if (!valor) return '';
  try {
    const normalizado = String(valor).replace(/-/g, '+').replace(/_/g, '/');
    return Buffer.from(normalizado, 'base64').toString('utf8');
  } catch {
    return '';
  }
}

function extraerCuerpo(parte, mimePreferido) {
  if (!parte || typeof parte !== 'object') return '';
  if (String(parte.mimeType ?? '').toLowerCase() === mimePreferido && parte.body?.data) {
    return decodificarBase64Url(parte.body.data);
  }
  for (const hija of parte.parts ?? []) {
    const contenido = extraerCuerpo(hija, mimePreferido);
    if (contenido) return contenido;
  }
  return '';
}

function convertirTexto(valor) {
  if (valor === null || valor === undefined) return '';
  if (typeof valor === 'string') return valor.trim();
  if (Array.isArray(valor)) return valor.map(convertirTexto).filter(Boolean).join('\n').trim();
  if (typeof valor === 'object') {
    if (typeof valor.text === 'string') return valor.text.trim();
    if (typeof valor.value === 'string') return valor.value.trim();
  }
  return String(valor).trim();
}

function htmlATexto(html) {
  return String(html ?? '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n\s*\n+/g, '\n\n')
    .trim();
}

function normalizarCorreo(correo, indice) {
  const gmailId = String(correo.id ?? '').trim();
  const remitente = datosDireccion(correo, correo.from, 'From');
  const destinatario = datosDireccion(correo, correo.to, 'To');

  let contenido =
    convertirTexto(correo.text) ||
    convertirTexto(correo.textPlain) ||
    extraerCuerpo(correo.payload, 'text/plain');

  if (!contenido) {
    contenido = htmlATexto(
      convertirTexto(correo.html) ||
      extraerCuerpo(correo.payload, 'text/html') ||
      convertirTexto(correo.snippet),
    );
  }

  const contenidoTruncado = contenido.length > 15000;
  contenido = contenido.slice(0, 15000);

  let fechaEmail = convertirTexto(correo.date) || obtenerHeader(correo, 'Date');
  if (!fechaEmail && correo.internalDate) {
    const fechaCalculada = new Date(Number(correo.internalDate));
    if (!Number.isNaN(fechaCalculada.getTime())) fechaEmail = fechaCalculada.toISOString();
  }

  const messageId = limpiarPrefijo(
    correo.messageId || obtenerHeader(correo, 'Message-ID'),
    'Message-ID',
  );
  const id = gmailId || messageId || ('sin-id-' + indice + '-' + String(fechaEmail).slice(0, 19));
  const erroresEntrada = [];
  if (!gmailId) erroresEntrada.push('El mensaje no contiene el ID de Gmail');
  if (!remitente.email) erroresEntrada.push('No se pudo determinar el remitente');
  if (!contenido) erroresEntrada.push('El correo no contiene texto procesable');

  const registroPrevio = registrosPorId.get(id) ?? null;

  return {
    json: {
      id,
      gmail_id: gmailId,
      thread_id: String(correo.threadId ?? '').trim(),
      message_id: messageId,
      fecha_email: fechaEmail,
      remitente_email: remitente.email,
      destinatario_email: destinatario.email,
      asunto: limpiarPrefijo(correo.subject || obtenerHeader(correo, 'Subject'), 'Subject'),
      contenido,
      contenido_truncado: contenidoTruncado,
      remitente_nombre: remitente.nombre || remitente.email.split('@')[0] || 'remitente',
      correo_valido: erroresEntrada.length === 0,
      errores_entrada: erroresEntrada,
      es_duplicado: Boolean(registroPrevio),
      estado_previo: String(registroPrevio?.estado_procesamiento ?? ''),
      etapa_actual: 'VALIDACION_ENTRADA',
      estado_procesamiento: 'RECIBIDO',
      requiere_revision_humana: erroresEntrada.length > 0,
    },
  };
}

return mensajes.map(normalizarCorreo);

const errores = Array.isArray($json.errores_entrada)
  ? $json.errores_entrada.join('; ')
  : 'El correo no superó la validación de entrada';

return {
  json: {
    ...$json,
    estado_procesamiento: 'REQUIERE_REVISION',
    etapa_error: 'VALIDACION_ENTRADA',
    mensaje_error: errores,
    justificacion: errores,
    resumen_breve: 'Correo recibido con datos incompletos',
    requiere_revision_humana: true,
    respuesta_generada: false,
    fecha_procesamiento: $now.setZone('America/Argentina/Buenos_Aires').toISO(),
  },
};

const originales = $('¿Duplicado?').all(1);
const original = originales[$itemIndex]?.json ?? {};
const error = $json.error ?? $json.execution?.error ?? null;
const mensaje = String(error?.message ?? error ?? '').slice(0, 1000);

return {
  json: {
    ...original,
    reserva_confirmada: !error,
    etapa_actual: error ? 'RESERVA_SHEETS' : 'CLASIFICACION_IA',
    estado_procesamiento: error ? 'ERROR_REINTENTABLE' : 'PROCESANDO',
    etapa_error: error ? 'RESERVA_SHEETS' : '',
    mensaje_error: error ? mensaje || 'No se pudo reservar el correo en Sheets' : '',
    requiere_revision_humana: error ? true : Boolean(original.requiere_revision_humana),
  },
};

/*
 * La salida de IA nunca debe detener el lote completo.
 * Si Ollama falla o devuelve JSON inválido, primero se intenta un fallback
 * determinista para solicitudes de reunión con fecha y hora concretas.
 */

const originales = $('¿Reserva confirmada?').all(0);
const correoOriginal = originales[$itemIndex]?.json ?? {};
const errorNodo = $json.error ?? $json.execution?.error ?? null;

function normalizarTexto(valor) {
  return String(valor ?? '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function fallbackDeterminista(mensaje, respuestaCruda = '') {
  const original = String(correoOriginal.contenido ?? '');
  const texto = normalizarTexto(original);
  const esReunion = /\b(reunion|meeting|llamada|videollamada|videoconferencia|meet)\b/i.test(texto);

  let fechaTexto = null;
  if (texto.includes('pasado manana')) {
    fechaTexto = 'pasado mañana';
  } else if (texto.includes('manana')) {
    fechaTexto = 'mañana';
  } else if (texto.includes('hoy')) {
    fechaTexto = 'hoy';
  } else {
    const fechaExplicita = original.match(/\b(?:\d{4}-\d{2}-\d{2}|\d{1,2}[/-]\d{1,2}[/-]\d{4})\b/);
    const diaSemana = texto.match(/\b(lunes|martes|miercoles|jueves|viernes|sabado|domingo)\b/);
    fechaTexto = fechaExplicita?.[0] ?? diaSemana?.[0] ?? null;
  }

  let hora = null;
  const horaCompleta = original.match(/\b([01]?\d|2[0-3])[:.]([0-5]\d)\b/);
  const horaSimple = original.match(/(?:a\s+las?|hora\s*)\s*([01]?\d|2[0-3])\s*(?:h|hs)?\b/i);
  if (horaCompleta) {
    hora = String(horaCompleta[1]).padStart(2, '0') + ':' + horaCompleta[2];
  } else if (horaSimple) {
    hora = String(horaSimple[1]).padStart(2, '0') + ':00';
  }

  let duracion = 30;
  let duracionDefault = true;
  const minutos = original.match(/\b(\d{1,3})\s*(?:min|minuto|minutos)\b/i);
  const horas = original.match(/\b(\d+(?:[.,]\d+)?)\s*(?:h|hs|hora|horas)\b/i);
  if (minutos) {
    const valor = Number(minutos[1]);
    if (Number.isInteger(valor) && valor > 0 && valor <= 480) {
      duracion = valor;
      duracionDefault = false;
    }
  } else if (/\bmedia\s+hora\b/i.test(texto)) {
    duracion = 30;
    duracionDefault = false;
  } else if (/\buna\s+hora\b/i.test(texto)) {
    duracion = 60;
    duracionDefault = false;
  } else if (horas) {
    const valor = Math.round(Number(String(horas[1]).replace(',', '.')) * 60);
    if (Number.isInteger(valor) && valor > 0 && valor <= 480) {
      duracion = valor;
      duracionDefault = false;
    }
  }

  if (esReunion && fechaTexto && hora) {
    const esVenta = /\b(cliente|proyecto|presupuesto|propuesta|demo|venta|comercial)\b/i.test(texto);
    return {
      json: {
        ...correoOriginal,
        categoria: esVenta ? 'VENTAS' : 'PERSONAL',
        prioridad: 'Media',
        requiere_respuesta: true,
        requiere_revision_humana: false,
        justificacion: 'Solicitud de reunión reconocida mediante fallback determinista',
        resumen_breve: 'Solicita comprobar disponibilidad para una reunión',
        accion_recomendada: 'Comprobar disponibilidad y responder',
        reunion_detectada: true,
        accion_calendario: 'COMPROBAR_HORARIO',
        fecha_texto: fechaTexto,
        hora,
        duracion_minutos: duracion,
        duracion_default: duracionDefault,
        titulo_evento: String(correoOriginal.asunto ?? 'Reunión').slice(0, 200),
        estado_procesamiento: 'CLASIFICADO_FALLBACK',
        etapa_actual: 'CLASIFICACION_COMPLETADA',
        etapa_error: 'CLASIFICACION_IA',
        mensaje_error: String(mensaje).slice(0, 1000),
        respuesta_ia_cruda: String(respuestaCruda).slice(0, 1000),
        error_ia: true,
        fallback_determinista: true,
        clasificacion_utilizable: true,
      },
    };
  }

  return {
    json: {
      ...correoOriginal,
      categoria: 'INFORMATIVO',
      prioridad: 'Media',
      requiere_respuesta: false,
      requiere_revision_humana: true,
      justificacion: 'No fue posible clasificar el correo automáticamente',
      resumen_breve: 'Clasificación de IA pendiente de revisión',
      accion_recomendada: 'Revisar manualmente',
      reunion_detectada: false,
      accion_calendario: 'NINGUNA',
      fecha_texto: null,
      hora: null,
      duracion_minutos: null,
      titulo_evento: null,
      estado_procesamiento: 'ERROR_CONTROLADO',
      etapa_actual: 'CLASIFICACION_IA',
      etapa_error: 'CLASIFICACION_IA',
      mensaje_error: String(mensaje).slice(0, 1000),
      respuesta_ia_cruda: String(respuestaCruda).slice(0, 1000),
      error_ia: true,
      fallback_determinista: false,
      clasificacion_utilizable: false,
    },
  };
}

if (errorNodo) {
  return fallbackDeterminista(errorNodo.message ?? errorNodo);
}

const respuesta = $json.text ?? $json.output ?? $json.response ?? $json;
let resultadoIA;

try {
  if (typeof respuesta === 'object' && respuesta !== null && !Array.isArray(respuesta)) {
    resultadoIA = respuesta;
  } else {
    const texto = String(respuesta ?? '').trim();
    const inicio = texto.indexOf('{');
    const final = texto.lastIndexOf('}');
    if (inicio === -1 || final === -1 || final < inicio) {
      return fallbackDeterminista('La IA no devolvió un objeto JSON', texto);
    }
    resultadoIA = JSON.parse(texto.slice(inicio, final + 1));
  }
} catch (error) {
  return fallbackDeterminista('JSON inválido de la IA: ' + error.message, respuesta);
}

const categorias = new Set(['URGENTE', 'SOPORTE', 'VENTAS', 'INFORMATIVO', 'PERSONAL']);
const prioridades = new Set(['Alta', 'Media', 'Baja']);
const acciones = new Set([
  'NINGUNA',
  'CONSULTAR_EVENTOS',
  'COMPROBAR_HORARIO',
  'BUSCAR_HUECOS',
  'CREAR_EVENTO',
]);

const categoria = String(resultadoIA.categoria ?? '').toUpperCase();
const prioridadCruda = String(resultadoIA.prioridad ?? '').toLowerCase();
const prioridad = prioridadCruda === 'alta' ? 'Alta' : prioridadCruda === 'baja' ? 'Baja' : 'Media';
const accion = String(resultadoIA.accion_calendario ?? 'NINGUNA').toUpperCase();
const duracionRecibida = Number(resultadoIA.duracion_minutos);
const requiereDuracion = accion === 'COMPROBAR_HORARIO' || accion === 'CREAR_EVENTO';
const duracionValida = Number.isInteger(duracionRecibida) && duracionRecibida > 0 && duracionRecibida <= 480;
const duracion = requiereDuracion ? (duracionValida ? duracionRecibida : 30) : null;
const validacionIncompleta = !categorias.has(categoria) || !prioridades.has(prioridad) || !acciones.has(accion);

return {
  json: {
    ...correoOriginal,
    ...resultadoIA,
    categoria: categorias.has(categoria) ? categoria : 'INFORMATIVO',
    prioridad,
    requiere_respuesta: resultadoIA.requiere_respuesta === true,
    requiere_revision_humana:
      resultadoIA.requiere_revision_humana === true || validacionIncompleta,
    reunion_detectada: resultadoIA.reunion_detectada === true,
    accion_calendario: acciones.has(accion) ? accion : 'NINGUNA',
    fecha_texto: resultadoIA.fecha_texto ?? null,
    hora: resultadoIA.hora ?? null,
    duracion_minutos: duracion,
    duracion_default: requiereDuracion && !duracionValida,
    titulo_evento: resultadoIA.titulo_evento ?? null,
    estado_procesamiento: validacionIncompleta ? 'REQUIERE_REVISION' : 'CLASIFICADO',
    etapa_actual: 'CLASIFICACION_COMPLETADA',
    etapa_error: validacionIncompleta ? 'VALIDACION_SALIDA_IA' : '',
    mensaje_error: validacionIncompleta ? 'La IA devolvió valores fuera del contrato esperado' : '',
    error_ia: validacionIncompleta,
    fallback_determinista: false,
    clasificacion_utilizable: acciones.has(accion),
  },
};

const accion = String($json.accion_calendario ?? 'NINGUNA');
const requiereRespuesta = $json.requiere_respuesta === true;
const sinAccion = accion === 'NINGUNA';
const necesitaRevision = !sinAccion || requiereRespuesta || $json.error_ia === true;

let motivo = '';
if ($json.error_ia === true) {
  motivo = $json.mensaje_error || 'La clasificación automática falló';
} else if (!sinAccion) {
  motivo = 'La acción ' + accion + ' todavía no está implementada en este workflow';
} else if (requiereRespuesta) {
  motivo = 'El correo requiere respuesta, pero no corresponde a la plantilla de disponibilidad';
}

return {
  json: {
    ...$json,
    estado_procesamiento: necesitaRevision ? 'REQUIERE_REVISION' : 'COMPLETADO_SIN_ACCION',
    etapa_error: necesitaRevision ? ($json.etapa_error || 'ENRUTAMIENTO') : '',
    mensaje_error: necesitaRevision ? motivo : '',
    requiere_revision_humana: necesitaRevision || $json.requiere_revision_humana === true,
    respuesta_generada: false,
    borrador_generado: false,
    fecha_procesamiento: $now.setZone('America/Argentina/Buenos_Aires').toISO(),
  },
};

const ZONA_HORARIA = 'America/Argentina/Buenos_Aires';

function devolverError(mensaje) {
  return {
    json: {
      ...$json,
      fecha_inicio: null,
      fecha_fin: null,
      fecha_calendario_resuelta: false,
      disponibilidad_consultada: false,
      estado_procesamiento: 'REQUIERE_REVISION',
      etapa_actual: 'RESOLVER_FECHA',
      etapa_error: 'RESOLVER_FECHA',
      mensaje_error: mensaje,
      error_calendario: mensaje,
      requiere_revision_humana: true,
    },
  };
}

function normalizarTexto(valor) {
  return String(valor ?? '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

const fechaTexto = normalizarTexto($json.fecha_texto);
const horaTexto = String($json.hora ?? '').trim();
const duracionRecibida = Number($json.duracion_minutos);
const duracionValida = Number.isInteger(duracionRecibida) && duracionRecibida > 0 && duracionRecibida <= 480;
const duracion = duracionValida ? duracionRecibida : 30;

let referencia = DateTime.fromISO(String($json.fecha_email ?? ''), { setZone: true });
if (!referencia.isValid) referencia = $now;
const hoy = referencia.setZone(ZONA_HORARIA).startOf('day');
let fechaBase = null;

if (fechaTexto.includes('pasado manana')) {
  fechaBase = hoy.plus({ days: 2 });
} else if (fechaTexto.includes('manana')) {
  fechaBase = hoy.plus({ days: 1 });
} else if (fechaTexto.includes('hoy')) {
  fechaBase = hoy;
} else {
  const fechaISO = fechaTexto.match(/\b(\d{4})-(\d{2})-(\d{2})\b/);
  const fechaLocal = fechaTexto.match(/\b(\d{1,2})[/-](\d{1,2})[/-](\d{4})\b/);

  if (fechaISO) {
    fechaBase = DateTime.fromObject(
      { year: Number(fechaISO[1]), month: Number(fechaISO[2]), day: Number(fechaISO[3]) },
      { zone: ZONA_HORARIA },
    );
  } else if (fechaLocal) {
    fechaBase = DateTime.fromObject(
      { year: Number(fechaLocal[3]), month: Number(fechaLocal[2]), day: Number(fechaLocal[1]) },
      { zone: ZONA_HORARIA },
    );
  } else {
    const diasSemana = {
      lunes: 1,
      martes: 2,
      miercoles: 3,
      jueves: 4,
      viernes: 5,
      sabado: 6,
      domingo: 7,
    };
    const diaEncontrado = Object.keys(diasSemana).find((dia) => fechaTexto.includes(dia));
    if (diaEncontrado) {
      let diasHastaFecha = (diasSemana[diaEncontrado] - hoy.weekday + 7) % 7;
      if (diasHastaFecha === 0) diasHastaFecha = 7;
      fechaBase = hoy.plus({ days: diasHastaFecha });
    }
  }
}

if (!fechaBase || !fechaBase.isValid) {
  return devolverError('No se pudo interpretar la fecha: "' + ($json.fecha_texto ?? '') + '"');
}

const horaValida = horaTexto.match(/^([01]?\d|2[0-3]):([0-5]\d)$/);
if (!horaValida) {
  return devolverError('La hora no es válida: "' + horaTexto + '". Se esperaba HH:mm');
}

const inicio = fechaBase.set({
  hour: Number(horaValida[1]),
  minute: Number(horaValida[2]),
  second: 0,
  millisecond: 0,
});
const fin = inicio.plus({ minutes: duracion });

if (!inicio.isValid || !fin.isValid || fin <= inicio) {
  return devolverError('El intervalo calculado no es válido');
}

if (inicio < $now.setZone(ZONA_HORARIA).minus({ minutes: 5 })) {
  return devolverError('El horario solicitado ya quedó en el pasado');
}

return {
  json: {
    ...$json,
    duracion_minutos: duracion,
    duracion_default: $json.duracion_default === true || !duracionValida,
    fecha_inicio: inicio.toISO({ suppressMilliseconds: true }),
    fecha_fin: fin.toISO({ suppressMilliseconds: true }),
    fecha_calendario_resuelta: true,
    disponibilidad_consultada: false,
    estado_procesamiento: 'FECHA_RESUELTA',
    etapa_actual: 'CALENDARIO_DISPONIBILIDAD',
    etapa_error: '',
    mensaje_error: '',
    error_calendario: null,
  },
};

return {
  json: {
    ...$json,
    estado_procesamiento: 'REQUIERE_REVISION',
    etapa_error: $json.etapa_error || 'RESOLVER_FECHA',
    mensaje_error: $json.mensaje_error || $json.error_calendario || 'Fecha u hora inválida',
    requiere_revision_humana: true,
    respuesta_generada: false,
    borrador_generado: false,
    fecha_procesamiento: $now.setZone('America/Argentina/Buenos_Aires').toISO(),
  },
};

const candidatos = $('¿Es una fecha válida?').all(0);
const datosCorreo = candidatos[$itemIndex]?.json ?? {};

const errorNodo = $json.error ?? $json.execution?.error ?? null;
if (errorNodo) {
  const mensaje = String(errorNodo.message ?? errorNodo).slice(0, 1000);
  return {
    json: {
      ...datosCorreo,
      disponibilidad_consultada: false,
      horario_disponible: null,
      estado_procesamiento: 'ERROR_CONTROLADO',
      etapa_actual: 'CALENDARIO_DISPONIBILIDAD',
      etapa_error: 'CALENDARIO_DISPONIBILIDAD',
      mensaje_error: mensaje,
      error_calendario: mensaje,
      requiere_revision_humana: true,
    },
  };
}

const valor = $json.available;
const valido = valor === true || valor === false || valor === 'true' || valor === 'false';
if (!valido) {
  return {
    json: {
      ...datosCorreo,
      disponibilidad_consultada: false,
      horario_disponible: null,
      estado_procesamiento: 'ERROR_CONTROLADO',
      etapa_error: 'CALENDARIO_RESPUESTA',
      mensaje_error: 'Google Calendar no devolvió un booleano de disponibilidad',
      error_calendario: 'Google Calendar no devolvió un booleano de disponibilidad',
      requiere_revision_humana: true,
    },
  };
}

return {
  json: {
    ...datosCorreo,
    disponibilidad_consultada: true,
    horario_disponible: valor === true || valor === 'true',
    estado_procesamiento: 'DISPONIBILIDAD_CONFIRMADA',
    etapa_actual: 'DISPONIBILIDAD_CONFIRMADA',
    etapa_error: '',
    mensaje_error: '',
    error_calendario: null,
  },
};

return {
  json: {
    ...$json,
    estado_procesamiento: 'ERROR_CONTROLADO',
    etapa_error: $json.etapa_error || 'CALENDARIO_DISPONIBILIDAD',
    mensaje_error: $json.mensaje_error || 'No se pudo consultar Google Calendar',
    requiere_revision_humana: true,
    respuesta_generada: false,
    borrador_generado: false,
    fecha_procesamiento: $now.setZone('America/Argentina/Buenos_Aires').toISO(),
  },
};

return {
  json: {
    ...$json,
    estado_procesamiento: 'COMPLETADO_SIN_RESPUESTA',
    requiere_revision_humana: $json.requiere_revision_humana === true,
    respuesta_generada: false,
    borrador_generado: false,
    fecha_procesamiento: $now.setZone('America/Argentina/Buenos_Aires').toISO(),
  },
};

function escaparHtml(valor) {
  return String(valor ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

const nombre = escaparHtml($json.remitente_nombre || '');
const fecha = escaparHtml($json.fecha_texto || 'la fecha indicada');
const hora = escaparHtml($json.hora || 'el horario indicado');
const saludo = nombre ? ('Hola ' + nombre + ':') : 'Hola:';

const cuerpoHtml = $json.horario_disponible === true
  ? '<p>' + saludo + '</p><p>El horario solicitado para ' + fecha + ' a las ' + hora + ' está disponible.</p><p>Si te parece bien, podemos confirmar la reunión.</p><p>Saludos.</p>'
  : '<p>' + saludo + '</p><p>El horario solicitado para ' + fecha + ' a las ' + hora + ' no está disponible.</p><p>¿Podrías indicarme otros días u horarios posibles?</p><p>Saludos.</p>';

return {
  json: {
    ...$json,
    cuerpo_html: cuerpoHtml,
    respuesta_preparada: true,
    etapa_actual: 'PREPARAR_BORRADOR',
  },
};

const datos = { ...$json };
const errores = [];
const destinatario = String(datos.remitente_email ?? '').trim();
const threadId = String(datos.thread_id ?? '').trim();
const cuerpoHtml = String(datos.cuerpo_html ?? '').trim()
  .replace(/^\x60\x60\x60(?:html)?\s*/i, '')
  .replace(/\s*\x60\x60\x60$/i, '')
  .trim();

if (!destinatario || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(destinatario)) {
  errores.push('El remitente no contiene una dirección válida');
}
if (!threadId) errores.push('No se encontró el thread_id');
if (!cuerpoHtml) errores.push('No se generó contenido HTML');

const asuntoOriginal = String(datos.asunto ?? '').trim() || 'Sin asunto';
const asuntoBorrador = /^re\s*:/i.test(asuntoOriginal) ? asuntoOriginal : ('Re: ' + asuntoOriginal);

return {
  json: {
    ...datos,
    destinatario_borrador: destinatario,
    asunto_borrador: asuntoBorrador,
    cuerpo_html: cuerpoHtml,
    respuesta_preparada: errores.length === 0,
    estado_procesamiento: errores.length ? 'ERROR_CONTROLADO' : 'BORRADOR_PREPARADO',
    etapa_actual: 'PREPARAR_BORRADOR',
    etapa_error: errores.length ? 'PREPARAR_BORRADOR' : '',
    mensaje_error: errores.join('; '),
    requiere_revision_humana: errores.length > 0 || datos.requiere_revision_humana === true,
    borrador_generado: false,
    evento_creado: false,
  },
};

return {
  json: {
    ...$json,
    estado_procesamiento: 'ERROR_CONTROLADO',
    etapa_error: $json.etapa_error || 'PREPARAR_BORRADOR',
    mensaje_error: $json.mensaje_error || 'No se pudo preparar el borrador',
    requiere_revision_humana: true,
    respuesta_generada: false,
    borrador_generado: false,
    fecha_procesamiento: $now.setZone('America/Argentina/Buenos_Aires').toISO(),
  },
};

const preparados = $('¿Borrador preparado?').all(0);
const datos = preparados[$itemIndex]?.json ?? {};

const errorNodo = $json.error ?? $json.execution?.error ?? null;
if (errorNodo) {
  const mensaje = String(errorNodo.message ?? errorNodo).slice(0, 1000);
  return {
    json: {
      ...datos,
      respuesta_generada: false,
      borrador_generado: false,
      estado_procesamiento: 'ERROR_CONTROLADO',
      etapa_error: 'CREAR_BORRADOR_GMAIL',
      mensaje_error: mensaje,
      requiere_revision_humana: true,
      fecha_procesamiento: $now.setZone('America/Argentina/Buenos_Aires').toISO(),
    },
  };
}

const draftId = $json.id ?? $json.draftId ?? null;
const mensajeBorradorId = $json.message?.id ?? $json.messageId ?? null;

return {
  json: {
    ...datos,
    draft_id: draftId,
    mensaje_borrador_id: mensajeBorradorId,
    respuesta_generada: true,
    borrador_generado: true,
    estado_procesamiento: 'COMPLETADO_BORRADOR',
    etapa_actual: 'COMPLETADO',
    etapa_error: '',
    mensaje_error: '',
    fecha_procesamiento: $now.setZone('America/Argentina/Buenos_Aires').toISO(),
  },
};

const errorNodo = $json.error ?? $json.execution?.error ?? null;
return {
  json: {
    ...$json,
    registro_final_exitoso: !errorNodo,
    error_registro_final: errorNodo ? String(errorNodo.message ?? errorNodo).slice(0, 1000) : '',
  },
};
